/* MuseScore SVG review page. Data is generated by build-musescore.mjs. */
(function () {
  "use strict";
  const DATA = window.MUSESCORE_REVIEW;
  const $ = (id) => document.getElementById(id);
  const els = {
    meta: $("meta"), renderer: $("renderer"), list: $("list"), empty: $("empty"), pagination: $("pagination"),
    q: $("q"), conversion: $("conversion"), review: $("review"), checker: $("checker"), grade: $("grade"), provenance: $("provenance"), pageSize: $("pageSize"), tpl: $("card-tpl"),
  };
  if (!DATA || !window.LilyletLib) {
    els.renderer.textContent = "缺少 musescore-data.js 或 Lilylet bundle：请先运行 npm run omr-review-musescore";
    els.renderer.classList.add("err");
    return;
  }
  const toUrl = (p) => "../" + p.split("/").map(encodeURIComponent).join("/");
  const OPTIONS = { scale: 40, adjustPageHeight: true, adjustPageWidth: true, breaks: "auto", pageWidth: 2100, pageHeight: 2970, header: "none" };
  let toolkit = null;
  let page = 1;
  let queue = [];
  let busy = false;
  let cards = [];
  const renderUrls = new WeakMap();

  const toolkitReady = new Promise((resolve, reject) => {
    const start = () => {
      const v = window.verovio;
      if (!v) return reject(new Error("verovio script not loaded"));
      const make = () => {
        try {
          toolkit = new v.toolkit();
          if (v.enableLogToBuffer) v.enableLogToBuffer(true);
          if (v.enableLog && v.LOG_WARNING !== undefined) v.enableLog(v.LOG_WARNING);
          resolve(toolkit);
        } catch (e) { reject(e); }
      };
      if (v.module.calledRun) make(); else v.module.onRuntimeInitialized = make;
    };
    if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", start); else start();
  });
  toolkitReady.then((tk) => {
    els.renderer.textContent = `Verovio ${tk.getVersion ? tk.getVersion() : "已加载"} · ${DATA.scope}`;
    pump();
  }, (e) => {
    els.renderer.textContent = "Verovio 加载失败：" + (e && e.message ? e.message : e);
    els.renderer.classList.add("err");
  });

  const tag = (text, cls) => { const s = document.createElement("span"); s.className = "tag tag-st-" + cls; s.textContent = text; return s; };
  const statusClass = (value) => value === "manual" ? "manual" : value === "failed" || value === "fail" ? "failed" : value === "pass" ? "pass" : value === "draft" ? "draft" : "pending";
  const copy = async (text) => {
    if (!text) return false;
    if (navigator.clipboard && window.isSecureContext) { try { await navigator.clipboard.writeText(text); return true; } catch (_) {} }
    const ta = document.createElement("textarea"); ta.value = text; ta.readOnly = true; ta.style.position = "fixed"; ta.style.opacity = "0"; document.body.appendChild(ta); ta.select(); let ok = false;
    try { ok = document.execCommand("copy"); } catch (_) {} ta.remove(); return ok;
  };
  const addCopy = (parent, label, value) => {
    if (!value) return;
    const b = document.createElement("button"); b.type = "button"; b.className = "render-btn"; b.textContent = label;
    b.addEventListener("click", async () => { b.textContent = (await copy(value)) ? "已复制" : "复制失败"; setTimeout(() => { b.textContent = label; }, 1400); });
    parent.appendChild(b);
  };
  const renderLyl = (code) => {
    const L = window.LilyletLib;
    const doc = L.parseCode(code);
    const warnings = (L.getParseWarnings ? L.getParseWarnings() : []).map((w) => w.message);
    const mei = L.meiEncoder.encode(doc);
    toolkit.setOptions(OPTIONS);
    if (!toolkit.loadData(mei)) throw new Error("Verovio 无法载入 MEI\n" + (toolkit.getLog() || ""));
    const logs = (toolkit.getLog() || "").split("\n").map((s) => s.trim()).filter(Boolean);
    const pages = [];
    for (let p = 1; p <= toolkit.getPageCount(); p++) pages.push(toolkit.renderToSVG(p));
    return { pages, measures: doc.measures.length, warnings: warnings.concat(logs) };
  };
  const releaseUrls = (card) => { for (const u of (renderUrls.get(card) || [])) URL.revokeObjectURL(u); renderUrls.delete(card); };
  const fillRender = (card) => {
    const item = card._item; const box = card.querySelector(".render"); const cap = card.querySelector(".cap-text");
    if (card._rendered) return; card._rendered = true; releaseUrls(card); box.replaceChildren();
    if (!item.code) { const p = document.createElement("p"); p.className = "placeholder"; p.textContent = item.error || "没有 Lilylet 草稿，无法渲染。"; box.appendChild(p); return; }
    try {
      const result = renderLyl(item.code); const urls = [];
      for (let i = 0; i < result.pages.length; i++) {
        const url = URL.createObjectURL(new Blob([result.pages[i]], { type: "image/svg+xml" })); urls.push(url);
        const img = document.createElement("img"); img.src = url; img.alt = `${item.name} Lilylet 第 ${i + 1} 页`; img.loading = "lazy"; img.decoding = "async"; box.appendChild(img);
      }
      renderUrls.set(card, urls); cap.textContent = `Lilylet 渲染 · ${result.measures} 小节 · ${result.pages.length} 页`;
      const warnings = card.querySelector(".notes");
      if (result.warnings.length) warnings.textContent += (warnings.textContent ? "\n" : "") + "渲染警告：\n" + result.warnings.join("\n");
    } catch (e) {
      const p = document.createElement("p"); p.className = "placeholder err"; p.textContent = "Lilylet 渲染失败：" + (e && e.message ? e.message : e); box.appendChild(p);
    }
  };
  const pump = () => {
    if (busy || !toolkit || !queue.length) return;
    busy = true; const card = queue.shift(); setTimeout(() => { try { if (!card._retired) fillRender(card); } finally { busy = false; pump(); } }, 0);
  };
  const observe = new IntersectionObserver((entries) => {
    for (const e of entries) if (e.isIntersecting) { observe.unobserve(e.target); queue.push(e.target); }
    pump();
  }, { rootMargin: "500px 0px" });

  const makeCard = (item) => {
    const card = els.tpl.content.firstElementChild.cloneNode(true); card._item = item; card.id = item.id;
    card.querySelector(".card-name").textContent = item.name; card.querySelector(".path").textContent = item.source;
    const tags = card.querySelector(".tags"); tags.append(tag(item.provenance === "manual" ? "手工转写" : "自动草稿", statusClass(item.provenance === "manual" ? "manual" : "draft")));
    tags.append(tag("转换：" + item.conversion, statusClass(item.conversion)));
    tags.append(tag("审核：" + item.review, statusClass(item.review)));
    tags.append(tag("结构：" + item.checker, statusClass(item.checker)));
    if (item.quality) {
      const q = item.quality;
      tags.append(tag({ consistent: "自洽", flagged: "有标记", broken: "往返失败" }[q.grade] || q.grade, q.grade));
      tags.append(tag(`一致小节 ${q.fineMeasures}/${q.measures}`, q.fineMeasures === q.measures ? "pass" : "flagged"));
    }
    if (item.rendered) tags.append(tag("已有批量渲染", "pass"));
    if (item.stale) tags.append(tag("草稿哈希不一致", "stale"));
    const sourceImg = card.querySelector(".source-paper img"); sourceImg.src = toUrl(item.source); sourceImg.alt = "MuseScore 源 SVG：" + item.name;
    const box = card.querySelector(".render");
    if (!item.code) { const p = document.createElement("p"); p.className = "placeholder"; p.textContent = item.error || "没有自动草稿。"; box.appendChild(p); }
    else { const p = document.createElement("p"); p.className = "placeholder"; p.textContent = "等待 Lilylet 渲染…"; box.appendChild(p);
      if (item.code.length > 3000) {
        p.textContent = "较长草稿：按需渲染。";
        const b = document.createElement("button"); b.type = "button"; b.className = "render-btn"; b.textContent = "渲染";
        b.onclick = () => { b.disabled = true; b.textContent = "渲染中…"; queue.unshift(card); pump(); }; box.appendChild(b);
      } else observe.observe(card);
    }
    const qualityNotes = item.quality ? [
      Object.keys(item.quality.flags || {}).length ? "小节标记：" + Object.entries(item.quality.flags).map(([k, v]) => `${k}×${v}`).join("，") : "",
      item.quality.unrepresented && item.quality.unrepresented.length ? "未转写的元素类别：" + item.quality.unrepresented.join("、") : "",
    ] : [];
    const notes = card.querySelector(".notes"); notes.textContent = [item.reviewNotes, item.error, ...qualityNotes].filter(Boolean).join("\n");
    if (item.legacyCode) { const l = card.querySelector(".legacy"); l.hidden = false; l.querySelector(".legacy-code").textContent = item.legacyCode; }
    const details = card.querySelector(".local-path"); details.textContent = `源哈希：${item.sourceHash}` + (item.reviewedDraftHash ? `\n草稿哈希：${item.reviewedDraftHash}` : "");
    if (item.draftLocal) addCopy(details, "复制草稿本地路径", item.draftLocal);
    addCopy(details, "复制源文件本地路径", pathForSource(item.source));
    card.querySelector(".code").textContent = item.code || "";
    return card;
  };
  const pathForSource = (source) => source ? `${DATA.root}/${source}` : "";
  const filtered = () => {
    const q = els.q.value.trim().toLowerCase();
    return DATA.items.filter((x) => (!q || [x.name, x.source, x.reviewNotes, x.error].join(" ").toLowerCase().includes(q)) && (!els.conversion.value || x.conversion === els.conversion.value) && (!els.review.value || x.review === els.review.value) && (!els.checker.value || x.checker === els.checker.value) && (!els.grade.value || (x.quality && x.quality.grade === els.grade.value)) && (!els.provenance.value || x.provenance === els.provenance.value));
  };
  const redraw = () => {
    queue = []; cards.forEach((c) => { c._retired = true; observe.unobserve(c); releaseUrls(c); });
    els.list.replaceChildren(); const all = filtered(); const size = Number(els.pageSize.value); const pages = Math.max(1, Math.ceil(all.length / size)); page = Math.min(page, pages);
    const shown = all.slice((page - 1) * size, page * size); cards = shown.map(makeCard); cards.forEach((c) => els.list.appendChild(c)); els.empty.hidden = shown.length !== 0;
    els.pagination.replaceChildren();
    const prev = document.createElement("button"); prev.type = "button"; prev.textContent = "上一页"; prev.disabled = page <= 1; prev.onclick = () => { page--; redraw(); window.scrollTo(0, 0); };
    const next = document.createElement("button"); next.type = "button"; next.textContent = "下一页"; next.disabled = page >= pages; next.onclick = () => { page++; redraw(); window.scrollTo(0, 0); };
    const label = document.createElement("span"); label.textContent = `${page} / ${pages} · ${all.length} 条`;
    els.pagination.append(prev, label, next);
    els.meta.textContent = `显示 ${shown.length} / ${all.length} 条（总计 ${DATA.items.length}：自动条目 ${DATA.items.filter((x) => x.provenance === "automatic").length}，其中草稿 ${DATA.items.filter((x) => x.conversion === "draft").length}，手工版本 ${DATA.items.filter((x) => x.provenance === "manual").length}） · 仅限 _p0.svg；“自洽”只表示时值与往返检查一致，不代表与原图相符`;
  };
  for (const id of ["q", "conversion", "review", "checker", "grade", "provenance", "pageSize"]) els[id].addEventListener(id === "q" ? "input" : "change", () => { page = 1; redraw(); });
  redraw();
})();
